/* Export the model as CSS custom properties, JSON, or SVG. */
(function () {
  const G = (globalThis.GridCalc = globalThis.GridCalc || {});
  if (typeof module !== 'undefined') { require('./math.js'); require('./scene.js'); }
  const { round } = G.math;

  const px = (v) => `${round(v, 2)}px`;

  function toCss(model) {
    const { cfg, unit: u, view, margins, grids, type, baseline } = model;
    const g = grids[0];
    const m = margins.snapped;
    const rows = [
      '/* Generated by Grid Calculator — every length is a multiple of --u when snapping is on. */',
      ':root {',
      `  --u: ${px(u)};`,
      `  --page-width: ${px(cfg.layout === 'spread' ? view.width / 2 : view.width)};`,
      `  --page-height: ${px(view.height)};`,
      `  --canon-division: ${cfg.divisions};`,
      `  --margin-top: ${px(m.top)};`,
      `  --margin-bottom: ${px(m.bottom)};`,
      `  --margin-inner: ${px(m.inner)};`,
      `  --margin-outer: ${px(m.outer)};`,
    ];
    if (g && g.ok) {
      rows.push(
        `  --columns: ${cfg.columns};`,
        `  --column-width: ${px(g.columns[0].w)};`,
        `  --gutter: ${px(cfg.gutter * u)};`,
        `  --rows: ${cfg.rows};`,
        `  --row-height: ${px(g.modules[0].h)};`,
        `  --row-gutter: ${px(cfg.rowGutter * u)};`,
        `  --block-width: ${px(g.fitted.w)};`,
        `  --block-height: ${px(g.fitted.h)};`,
      );
    }
    rows.push(`  --baseline: ${px(baseline.step)};`);
    const name = (l) => l.label.replace('/', '-');
    model.power.x.forEach((l) => rows.push(`  --power-x-${name(l)}: ${px(l.pos)};`));
    model.power.y.forEach((l) => rows.push(`  --power-y-${name(l)}: ${px(l.pos)};`));
    type.scale.forEach((s) => rows.push(`  --font-size-${s.name}: ${px(s.size)};`, `  --line-height-${s.name}: ${px(s.leading)};`));
    rows.push('}', '');
    if (g && g.ok) {
      rows.push(
        '.grid {', '  display: grid;',
        '  grid-template-columns: repeat(var(--columns), var(--column-width));',
        '  column-gap: var(--gutter);', '  row-gap: var(--row-gutter);', '}', '',
      );
    }
    return rows.join('\n');
  }

  function toJson(model) {
    const { cfg, unit, view, margins, blocks, grids, type, baseline, integrity, stats, power } = model;
    const line = (l) => ({ fraction: l.label, position: l.pos, units: l.units, ideal: l.ideal, deviation: l.deviation, level: l.level });
    return {
      foundations: { setUp: { gridUnit: unit, canvasWidth: view.width, canvasHeight: view.height, layout: cfg.layout } },
      grids: {
        villardDeHonnecourtCanon: {
          divisions: cfg.divisions, snapMode: cfg.snapMode, margins,
          workAreas: blocks.map((b) => ({ id: b.id, x: b.x, y: b.y, width: b.w, height: b.h, units: b.units, deviation: b.deviation })),
        },
        modular: grids.map((g) => ({
          block: g.block.id, columns: g.columns.map(({ x, y, w, h }) => ({ x, y, width: w, height: h })),
          gutter: cfg.gutter * unit, rows: cfg.rows, rowGutter: cfg.rowGutter * unit,
        })),
        baseline: { step: baseline.step, units: baseline.units, origin: baseline.origin },
      },
      powerLines: {
        x: power.x.map(line), y: power.y.map(line),
        anchors: power.anchors.map((a) => ({ x: a.x, y: a.y, fx: a.fx, fy: a.fy, label: a.label, onDiagonal: a.strong, level: a.level })),
      },
      typography: Object.fromEntries(type.scale.map((s) => [s.name, { fontFamily: cfg.fontFamily, fontSize: s.size, lineHeight: s.leading, lineHeightUnits: s.leadingUnits }])),
      integrity: { edges: integrity.total, onGrid: integrity.onGrid },
      stats,
      settings: cfg,
    };
  }

  const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const n = (v) => round(v, 3);

  function toSvg(model, scene) {
    const { cfg, view } = model;
    const styles = G.scene.roleStyles(cfg);
    const body = scene.map((p) => {
      const st = styles[p.role] || {};
      if (p.t === 'line') {
        const dash = st.dash ? ` stroke-dasharray="${st.dash.join(' ')}"` : '';
        return `<line x1="${n(p.x1)}" y1="${n(p.y1)}" x2="${n(p.x2)}" y2="${n(p.y2)}" stroke="${st.stroke}" stroke-opacity="${st.alpha}" stroke-width="${n(st.w)}"${dash}/>`;
      }
      if (p.t === 'image') {
        const url = G.assets && G.assets.dataUrl ? G.assets.dataUrl(p.assetId) : null;
        if (!url) return `<rect x="${n(p.x)}" y="${n(p.y)}" width="${n(p.w)}" height="${n(p.h)}" fill="${st.fill}" fill-opacity="0.12" stroke="${st.stroke}" stroke-opacity="0.5" stroke-dasharray="4 3"/>`;
        return `<image href="${url}" x="${n(p.x)}" y="${n(p.y)}" width="${n(p.w)}" height="${n(p.h)}" preserveAspectRatio="${p.fit === 'cover' ? 'xMidYMid slice' : 'xMidYMid meet'}"/>`;
      }
      if (p.t === 'dot') {
        const fill = st.fill ? `fill="${st.fill}"` : 'fill="none"';
        const stroke = st.stroke ? ` stroke="${st.stroke}" stroke-opacity="${st.alpha}" stroke-width="${n(st.w)}"` : '';
        return `<circle cx="${n(p.x)}" cy="${n(p.y)}" r="${p.r}" ${fill}${stroke}/>`;
      }
      if (p.t === 'rect') {
        const fill = st.fill && p.fill !== false ? `fill="${st.fill}" fill-opacity="${st.fillAlpha}"` : 'fill="none"';
        const stroke = st.stroke ? `stroke="${st.stroke}" stroke-opacity="${st.alpha}" stroke-width="${n(st.w)}"` : 'stroke="none"';
        const dash = st.dash ? ` stroke-dasharray="${st.dash.join(' ')}"` : '';
        return `<rect x="${n(p.x)}" y="${n(p.y)}" width="${n(p.w)}" height="${n(p.h)}" ${fill} ${stroke}${dash}/>`;
      }
      if (p.strs) return ''; // labels are screen-sized annotations; omitted from vector export
      const family = esc(p.family || 'sans-serif');
      return `<text x="${n(p.x)}" y="${n(p.y)}" font-family="${family}" font-size="${p.size}" font-weight="${p.weight || 'normal'}" fill="${st.fill}">${esc(p.str)}</text>`;
    }).filter(Boolean).join('\n  ');
    return `<svg xmlns="http://www.w3.org/2000/svg" width="${view.width}" height="${view.height}" viewBox="0 0 ${view.width} ${view.height}">\n  <rect width="100%" height="100%" fill="${cfg.cBg}"/>\n  ${body}\n</svg>\n`;
  }

  const gcd = (a, b) => (b ? gcd(b, a % b) : a);

  /** One measured element, as plain data. */
  function elementJson(model, it) {
    const src = model.cfg.elements.find((e) => e.id === it.id);
    const out = { id: it.id, role: it.role, slot: it.slot, fits: it.fits, overflow: round(it.overflow, 2), empty: Boolean(it.empty), box: it.box };
    if (it.kind === 'text') {
      const t = it.text;
      out.value = src.value;
      if (!it.empty) {
        out.text = {
          lineCount: t.lineCount, lines: t.lines.map((l) => l.text), firstBaseline: t.lines[0].y,
          font: t.familyLabel, weight: t.weight, size: t.size, leading: t.leading, leadingUnits: t.leadingUnits,
          align: t.align, stepRequested: t.stepRequested, stepUsed: t.stepUsed, steppedDown: t.steppedDown,
        };
      }
    } else {
      out.asset = { ...it.asset };
    }
    return out;
  }

  /** Everything an agent needs to place elements on this canvas, as plain data. */
  function toPlacementsJson(model) {
    const { cfg, unit, view, power, placements, baseline, margins } = model;
    const line = (l) => ({ fraction: l.label, position: l.pos, units: l.units, exact: l.exact });
    return {
      version: 1,
      canvas: {
        width: view.width, height: view.height, unit, ratio: placements.ratio, orientation: placements.orientation,
        layout: cfg.layout, widthUnits: round(view.width / unit, 3), heightUnits: round(view.height / unit, 3),
      },
      baseline: { step: baseline.step, units: baseline.units },
      canonMargins: margins.snapped,
      margin: placements.margin,
      lines: { x: power.x.map(line), y: power.y.map(line) },
      anchors: power.anchors.map((a) => ({ x: a.x, y: a.y, label: a.label, onDiagonal: a.strong })),
      focalPoints: placements.focalPoints,
      selected: placements.selected.id,
      templates: placements.templates,
      elements: model.elements.items.map((it) => elementJson(model, it)),
      rules: [
        `Every position, size and gap is a multiple of ${unit}px; text baselines sit on a ${baseline.step}px step.`,
        'Place an element by its anchorPoint; box edges are power lines unless onPowerLine is false.',
        'Boxes share edges where they touch — apply the column gutter inside each box, not between boxes.',
        'Choose the template whose character fits the content; keep one focal point per composition.',
      ],
    };
  }

  /** The same information as a compact, readable brief for an agent prompt. */
  function toBrief(model) {
    const { unit, view, power, placements: p, baseline } = model;
    const g = gcd(view.width, view.height);
    const pxu = (v) => `${round(v, 2)}px (${round(v / unit, 2)}u)`;
    const lines = (arr) => arr.map((l) => `${l.label}=${round(l.pos, 2)}`).join(', ');
    const sel = p.templates.find((t) => t.id === p.selected.id);
    const out = [
      `# Layout brief — ${view.width} × ${view.height} px (${p.orientation}, ratio ${p.ratio}${g > 1 && view.width / g < 40 ? `, ${view.width / g}:${view.height / g}` : ''})`,
      '',
      `Grid unit ${unit}px. Baseline step ${baseline.step}px (${baseline.units}u). Snap every element edge, size and gap to a multiple of ${unit}px and set text baselines on the ${baseline.step}px step.`,
      '',
      '## Margins',
      `Left ${pxu(p.margin.x.pos)}, right ${pxu(view.width - p.margin.xFar.pos)}, top ${pxu(p.margin.y.pos)}, bottom ${pxu(view.height - p.margin.yFar.pos)} (lines ${p.margin.x.label} / ${p.margin.y.label}).`,
      '',
      '## Power lines (px)',
      `x: ${lines(power.x)}`,
      `y: ${lines(power.y)}`,
      '',
      '## Focal points (ranked)',
      ...p.focalPoints.map((f) => `${f.rank}. ${f.label} → (${f.x}, ${f.y}) — ${f.note}${f.onDiagonal ? ' [on a canvas diagonal]' : ''}`),
      '',
      `## Suggested template: ${sel.name} (${sel.id})`,
      sel.note,
      ...sel.items.map((it) => `- ${it.role}: anchor ${it.anchor} at (${it.anchorPoint.x}, ${it.anchorPoint.y}); box x ${it.box.x}, y ${it.box.y}, ${it.box.width} × ${it.box.height}px — ${it.note}`),
      '',
      ...(model.elements.items.length ? ['', '## Content (measured)', ...model.elements.items.map((it) => {
        const b = it.box;
        const at = `box x ${b.x}, y ${b.y}, ${b.width} × ${b.height}px`;
        if (it.kind === 'asset') {
          const a = it.asset;
          return a.missing ? `- ${it.role}: no file yet — ${at}` : `- ${it.role} "${a.name}": ${a.width}×${a.height} source → ${at}, ${a.mode}${a.aspectError > 0.001 ? `, proportions shifted ${round(a.aspectError * 100, 1)}%` : ''}`;
        }
        if (it.empty) return `- ${it.role}: empty`;
        const t = it.text;
        const lead = t.steppedDown ? ' (stepped down to fit)' : '';
        return `- ${it.role} "${model.cfg.elements.find((e) => e.id === it.id).value.replace(/\s+/g, ' ').slice(0, 80)}": ${t.lineCount} line${t.lineCount === 1 ? '' : 's'}, ${t.familyLabel} ${t.weight} ${t.size}/${t.leading}px${lead}, ${at}${it.fits ? '' : `, OVERFLOWS by ${round(it.overflow, 1)}px`}`;
      })] : []),
      '',
      `Other templates for this format: ${p.available.filter((t) => t.id !== sel.id).map((t) => `${t.name} (${t.id})`).join('; ') || 'none'}.`,
      '',
      '## Rules',
      '- Boxes share edges where they touch; apply the column gutter inside each box.',
      '- Keep one dominant focal point and align secondary elements to the listed power lines.',
      '- Do not use every line — choose a few and let the rest stay empty.',
      p.offLines ? `- Note: ${p.offLines} template edges fall between power lines at the current depth; they are snapped to the grid instead.` : '',
    ];
    return `${out.join('\n').replace(/\n{3,}/g, '\n\n').trimEnd()}\n`;
  }

  G.exporters = { toCss, toJson, toSvg, toPlacementsJson, toBrief };
  if (typeof module !== 'undefined') module.exports = G.exporters;
})();
